  scales=new ScaleGestureDetector(c,new ScaleGestureDetector.SimpleOnScaleGestureListener(){public boolean onScaleBegin(ScaleGestureDetector d){multi=true;stopMotion();return true;}public boolean onScale(ScaleGestureDetector d){float previous=zoom;zoom=Math.max(1,Math.min(6,zoom*d.getScaleFactor()));float factor=zoom/previous;if(toon()){offset=(offset+d.getFocusY())*factor-d.getFocusY();layoutToon();clampOffset();syncPage();}else{panX=(panX+getWidth()/2f-d.getFocusX())*factor+d.getFocusX()-getWidth()/2f;panY=(panY+getHeight()/2f-d.getFocusY())*factor+d.getFocusY()-getHeight()/2f;}cancelTiles();invalidate();notifyChanged();return true;}});
