 void open(Book b,Progress p){stopMotion();joined=-1;cancel();book=b;progress=p;zoom=1;panX=panY=0;previews.clear();errors.clear();tiles.clear();layoutToon();offset=p.mode==3?tops[p.page]+heights[p.page]*p.fraction:0;clampOffset();invalidate();notifyChanged();}
