 void notifyChanged(){if(changed!=null&&book!=null)changed.run();}
 void layoutToon(){if(book==null)return;float width=Math.min(getWidth(),1000*getResources().getDisplayMetrics().density)*zoom;tops=new float[book.pages.size()];heights=new float[tops.length];float y=12;for(int i=0;i<tops.length;i++){Page p=book.pages.get(i);tops[i]=y;heights[i]=width*p.height/p.width;y+=heights[i]+8;}}
